import { forwardRef, type ButtonHTMLAttributes, type ReactNode } from "react";
import { cn } from "./cn.js";

type IconButtonSize = "sm" | "md";

export interface IconButtonProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "aria-label" | "children"> {
  /** Required accessible label. Used for both `aria-label` and `title`. */
  label: string;
  /** The icon node — typically a 16–20px `<svg>` from `@radix-ui/react-icons` or `lucide-react`. */
  icon: ReactNode;
  /** `sm` = 32×32px (desktop-only contexts). `md` = 40×40px (touch-target compliant). */
  size?: IconButtonSize;
}

const sizeClasses: Record<IconButtonSize, string> = {
  sm: "h-8 w-8",
  md: "h-10 w-10",
};

/**
 * Square icon-only button with a required accessible label. Establishes the
 * touch-target convention for icon controls: `md` (40px) on mobile-reachable
 * surfaces, `sm` (32px) for desktop-dense toolbars.
 */
export const IconButton = forwardRef<HTMLButtonElement, IconButtonProps>(function IconButton(
  { label, icon, size = "md", className, type = "button", ...rest },
  ref,
) {
  return (
    <button
      ref={ref}
      type={type}
      aria-label={label}
      title={label}
      className={cn(
        // Focus is a flush 2px edge: a transparent 1px border that recolors to
        // --ring plus a 1px outline against it at offset 0. Both halves are
        // required — the outline alone is 1px. `bg-clip-padding` keeps the
        // hover fill from bleeding under the transparent border.
        "inline-flex shrink-0 items-center justify-center rounded-md border border-transparent bg-clip-padding text-foreground transition hover:bg-surface-hover focus-visible:border-ring focus-visible:outline-solid focus-visible:outline-1 focus-visible:outline-offset-0 focus-visible:outline-ring disabled:cursor-not-allowed disabled:opacity-50",
        sizeClasses[size],
        className,
      )}
      {...rest}
    >
      {icon}
    </button>
  );
});
